});

interface RequestRecord {
  v: number;
  id: string;
  auth: string;
  challenge: string;
  method: string;
  path: string;
  body: unknown;
}

interface ResponseRecord {
  v: number;
  id: string;
  auth: string;
  status: number;
  body: unknown;
}

async function listen(
  onRequest: (socket: Socket, request: RequestRecord) => void,
  apiKey: string,
  autoProbe = true,
): Promise<string> {
  const endpoint = testEndpoint();
  const server = createServer((socket) => {
    let frame = Buffer.alloc(0);
    socket.on("data", (chunk: Buffer) => {
      frame = Buffer.concat([frame, chunk]);
      const newline = frame.indexOf(0x0a);
      if (newline === -1) return;
      const request = JSON.parse(frame.subarray(0, newline).toString("utf8")) as RequestRecord;
      if (autoProbe && request.method === "GET" && request.path === "/health") {
        socket.end(encodeResponse(signedProbeResponse(request, apiKey)));
      } else {
        onRequest(socket, request);
      }
    });
  });
  servers.push(server);
  if (process.platform !== "win32") unixEndpoints.push(endpoint);
  await new Promise<void>((resolve, reject) => {
    server.once("error", reject);
    server.listen(endpoint, resolve);
  });
  return endpoint;
}

function signedProbeResponse(request: RequestRecord, key: string): ResponseRecord {
  const status = 200;
  const proof = macHex(key, PROBE_RESPONSE_DOMAIN, [
    Buffer.from(request.id, "utf8"),
    Buffer.from(request.challenge, "utf8"),
    NONCE,
    u16(status),
  ]);
  return {
    v: IPC_PROTOCOL_VERSION,
    id: request.id,
    auth: `probe:${NONCE.toString("hex")}:${proof}`,
    status,
    body: { ok: true },
  };
}

function signedResponse(
  request: RequestRecord,
  key: string,
  status: number,
  body: unknown,
): ResponseRecord {
  const proof = macHex(key, RESPONSE_DOMAIN, [
    NONCE,
    Buffer.from(request.auth, "utf8"),
    Buffer.from(request.id, "utf8"),
    u16(status),
  ]);
  return {
    v: IPC_PROTOCOL_VERSION,
    id: request.id,
    auth: `response:${proof}`,
    status,
    body,
  };
}

function requestProofIsValid(request: RequestRecord, key: string): boolean {
  const [kind, nonceHex, proof, ...trailing] = request.auth.split(":");
  if (kind !== "request" || !nonceHex || !proof || trailing.length > 0) return false;
  const version = u16(request.v);
  const expected = macHex(key, REQUEST_DOMAIN, [
    Buffer.from(nonceHex, "hex"),
    version,
    Buffer.from(request.id, "utf8"),
    Buffer.from(request.method, "utf8"),
    Buffer.from(request.path, "utf8"),
    Buffer.from(JSON.stringify(request.body), "utf8"),
  ]);
  return nonceHex === NONCE.toString("hex") && proof === expected;
}

function macHex(key: string, domain: Buffer, fields: Buffer[]): string {
  const mac = createHmac("sha256", key);
  for (const field of [domain, ...fields]) {
    const length = Buffer.alloc(8);
    length.writeBigUInt64BE(BigInt(field.byteLength));
    mac.update(length);
    mac.update(field);
  }
  return mac.digest("hex");
}

function u16(value: number): Buffer {
  const encoded = Buffer.alloc(2);
  encoded.writeUInt16BE(value);
  return encoded;
}

function encodeResponse(response: ResponseRecord): string {
  return `${JSON.stringify(response)}\n`;
}

function makeClient(endpoint: string, key: string): ShodhIpcClient {
  return new ShodhIpcClient(endpoint, key, windowsTestHelper());
}

function windowsTestHelper(): WindowsIpcHelper | undefined {
  return process.platform === "win32"
    ? { command: process.execPath, args: ["-e", WINDOWS_TEST_HELPER, "--"] }
    : undefined;
}

function testEndpoint(): string {
  const suffix = `${process.pid}-${randomUUID()}`;
  return process.platform === "win32"
    ? `\\\\.\\pipe\\shodh-ipc-test-${suffix}`
    : join(tmpdir(), `shodh-ipc-test-${suffix}.sock`);
}

function closeServer(server: Server): Promise<void> {
  return new Promise((resolve) => {
    server.close(() => resolve());
  });
}

import { afterEach, describe, expect, it, vi } from "vitest";
import { DrainController, type TimerHandle } from "../drain";

type Result = { content: { type: string; text: string }[]; isError?: boolean };

const ABANDON: Result = {
  content: [{ type: "text", text: "ABANDONED" }],
  isError: true,
};

function real(text: string): Result {
  return { content: [{ type: "text", text }] };
}

function deferred<T>() {
  let resolve!: (value: T) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

interface FakeTimer {
  fn: () => void;
  ms: number;
  handle: number;
  cleared: boolean;
}

function makeHarness(opts?: { graceMs?: number; writable?: boolean }) {
  const graceMs = opts?.graceMs ?? 60_000;
  const shutdownCalls: string[] = [];
  const logs: string[] = [];
  const state = { writable: opts?.writable ?? true };
  const timers: FakeTimer[] = [];
  let nextHandle = 1;

  const controller = new DrainController<Result>({
    graceMs,
    abandonResult: ABANDON,
    isOutputWritable: () => state.writable,
    shutdown: (reason) => shutdownCalls.push(reason),
    log: (message) => logs.push(message),
    setTimer: (fn, ms) => {
      const handle = nextHandle++;
      timers.push({ fn, ms, handle, cleared: false });
      return handle as unknown as TimerHandle;
    },
    clearTimer: (handle) => {
      const timer = timers.find((t) => t.handle === (handle as unknown as number));
      if (timer) timer.cleared = true;
    },
  });

  return {
    controller,
    shutdownCalls,
    logs,
    state,
    timers,
    activeTimers: () => timers.filter((t) => !t.cleared),
    fireGraceTimer: () => {
      const active = timers.filter((t) => !t.cleared);
      if (active.length === 0) throw new Error("no active grace timer to fire");
      active[0].fn();
    },
  };
}

describe("DrainController — nothing in flight", () => {
  it("shuts down immediately on stdin EOF and schedules no grace timer", () => {
    const h = makeHarness();
    expect(h.controller.isDraining).toBe(false);
    h.controller.onStdinClose("eof");
    expect(h.shutdownCalls).toEqual(["eof"]);
    expect(h.timers).toHaveLength(0);
  });

  it("shuts down exactly once when both stdin end and close fire (double-fire guard)", () => {
    const h = makeHarness();
    h.controller.onStdinClose("end-fired");
    h.controller.onStdinClose("close-fired");
    expect(h.shutdownCalls).toEqual(["end-fired"]);
  });
});

describe("DrainController — draining in-flight calls", () => {
  it("delivers the real in-flight response before exiting on stdin EOF", async () => {
    const h = makeHarness();
    const work = deferred<Result>();
    const tracked = h.controller.track(() => work.promise);
    expect(h.controller.inFlightCount).toBe(1);

    // Host closes stdin mid-flight: must NOT exit yet, must arm the grace timer.
    h.controller.onStdinClose("eof");
    expect(h.controller.isDraining).toBe(true);
    expect(h.shutdownCalls).toHaveLength(0);
    expect(h.activeTimers()).toHaveLength(1);
    expect(h.logs.some((l) => l.includes("draining before shutdown"))).toBe(true);

    // Backend finishes: caller gets the REAL result, not the abandon result.
    work.resolve(real("REAL"));
    await expect(tracked).resolves.toEqual(real("REAL"));

    // Only now do we shut down, and the grace timer is cleared.
    expect(h.shutdownCalls).toHaveLength(1);
    expect(h.timers[0].cleared).toBe(true);
    expect(h.controller.inFlightCount).toBe(0);

    // A late output-loss signal after completion is a harmless no-op.
    h.controller.onOutputLost("late");
    expect(h.shutdownCalls).toHaveLength(1);
  });

  it("waits for ALL in-flight calls before shutting down", async () => {
    const h = makeHarness();
    const w1 = deferred<Result>();
    const w2 = deferred<Result>();
    const t1 = h.controller.track(() => w1.promise);
    const t2 = h.controller.track(() => w2.promise);
    expect(h.controller.inFlightCount).toBe(2);

    h.controller.onStdinClose("eof");

    w1.resolve(real("a"));
    await expect(t1).resolves.toEqual(real("a"));
    expect(h.shutdownCalls).toHaveLength(0); // one still in flight
    expect(h.controller.inFlightCount).toBe(1);

    w2.resolve(real("b"));
    await expect(t2).resolves.toEqual(real("b"));
    expect(h.shutdownCalls).toHaveLength(1);
  });

  it("decrements the in-flight count even when the tool call throws", async () => {
    const h = makeHarness();
    const tracked = h.controller.track(async () => {
      throw new Error("boom");
    });
    await expect(tracked).rejects.toThrow("boom");
    expect(h.controller.inFlightCount).toBe(0);
  });

  it("does not shut down when a call settles before any stdin EOF", async () => {
    const h = makeHarness();
    await expect(h.controller.track(async () => real("ok"))).resolves.toEqual(real("ok"));
    expect(h.shutdownCalls).toHaveLength(0);
    expect(h.controller.isDraining).toBe(false);
  });
});

describe("DrainController — grace window expiry", () => {
  it("abandons a hung in-flight call with an error result, then exits", async () => {
    const h = makeHarness();
    const work = deferred<Result>(); // backend never responds
    const tracked = h.controller.track(() => work.promise);

    h.controller.onStdinClose("eof");
    expect(h.shutdownCalls).toHaveLength(0);

    // Grace window elapses.
    h.fireGraceTimer();
    await expect(tracked).resolves.toEqual(ABANDON);
    expect(h.shutdownCalls).toHaveLength(1);
    expect(h.shutdownCalls[0]).toContain("grace window");
  });

  it("returns the abandon result immediately for calls that start after expiry", async () => {
    const h = makeHarness();
    const work = deferred<Result>();
    const t1 = h.controller.track(() => work.promise);
    h.controller.onStdinClose("eof");
    h.fireGraceTimer();
    await expect(t1).resolves.toEqual(ABANDON);

    const t2 = h.controller.track(async () => real("late"));
    await expect(t2).resolves.toEqual(ABANDON);
  });
});

describe("DrainController — output stream gone", () => {
  it("shuts down immediately if stdout is already unwritable when stdin closes mid-flight", () => {
    const h = makeHarness({ writable: false });
    const work = deferred<Result>();
    void h.controller.track(() => work.promise);

    h.controller.onStdinClose("eof");
    expect(h.shutdownCalls).toHaveLength(1);
    expect(h.shutdownCalls[0]).toContain("not writable");
    expect(h.timers).toHaveLength(0); // no drain attempted
  });

  it("abandons and exits if stdout dies during the drain window", async () => {
    const h = makeHarness();
    const work = deferred<Result>();
    const tracked = h.controller.track(() => work.promise);
    h.controller.onStdinClose("eof");
    expect(h.shutdownCalls).toHaveLength(0);

    // stdout dies mid-drain: cannot deliver, so exit now (no abandon write).
    h.state.writable = false;
    h.controller.onOutputLost("stdout gone");
    expect(h.shutdownCalls).toEqual(["stdout gone"]);

    // The underlying work still resolves to its real value; process is exiting.
    work.resolve(real("late"));
    await expect(tracked).resolves.toEqual(real("late"));
  });

  it("ignores output loss when not draining", () => {
    const h = makeHarness();
    h.controller.onOutputLost("noise");
    expect(h.shutdownCalls).toHaveLength(0);
  });
});

describe("DrainController — default wiring (no injected log/timers)", () => {
  afterEach(() => {
    vi.useRealTimers();
    vi.restoreAllMocks();
  });

  it("uses console.error and real timers, clearing the timer on a normal drain", async () => {
    vi.useFakeTimers();
    const errSpy = vi.spyOn(console, "error").mockImplementation(() => {});
    const shutdownCalls: string[] = [];
    const controller = new DrainController<Result>({
      graceMs: 5_000,
      abandonResult: ABANDON,
      isOutputWritable: () => true,
      shutdown: (reason) => shutdownCalls.push(reason),
    });

    const work = deferred<Result>();
    const tracked = controller.track(() => work.promise);
    controller.onStdinClose("eof");
    expect(errSpy).toHaveBeenCalled(); // default log sink

    work.resolve(real("ok"));
    await expect(tracked).resolves.toEqual(real("ok"));
    expect(shutdownCalls).toHaveLength(1);

    // The real grace timer was cleared, so advancing time triggers nothing more.
    vi.advanceTimersByTime(10_000);
    expect(shutdownCalls).toHaveLength(1);
  });

  it("fires the default real timer on grace expiry", async () => {
    vi.useFakeTimers();
    vi.spyOn(console, "error").mockImplementation(() => {});
    const shutdownCalls: string[] = [];
    const controller = new DrainController<Result>({
      graceMs: 5_000,
      abandonResult: ABANDON,
      isOutputWritable: () => true,
      shutdown: (reason) => shutdownCalls.push(reason),
    });

    const work = deferred<Result>(); // hung
    const tracked = controller.track(() => work.promise);
    controller.onStdinClose("eof");

    vi.advanceTimersByTime(5_000);
    await expect(tracked).resolves.toEqual(ABANDON);
    expect(shutdownCalls).toHaveLength(1);
  });
});

import { describe, expect, it, beforeEach, afterEach, beforeAll } from "vitest";
import * as fs from "fs";
import * as os from "os";
import * as path from "path";
import { spawnSync } from "child_process";
import {
  SERVER_PIDFILE,
  SHIM_PID_DIR,
  backendPidToReap,
  clearSpawnedServer,
  isPidAlive,
  liveSiblingShims,
  readSpawnedServerPid,
  recordSpawnedServer,
  registerShim,
  unregisterShim,
} from "../backend-lifecycle";

let tmpRoot: string;
// A pid that definitely existed and is definitely dead now (short-lived child).
let deadPid: number;

beforeAll(() => {
  const child = spawnSync(process.execPath, ["-e", ""], { stdio: "ignore" });
  if (child.pid === undefined) throw new Error("failed to spawn probe child");
  deadPid = child.pid;
});

beforeEach(() => {
  tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), "shodh-lifecycle-test-"));
});

afterEach(() => {
  fs.rmSync(tmpRoot, { recursive: true, force: true });
});

describe("isPidAlive", () => {
  it("is true for the current process and false for a dead pid", () => {
    expect(isPidAlive(process.pid)).toBe(true);
    expect(isPidAlive(deadPid)).toBe(false);
  });

  it("rejects garbage pids", () => {
    expect(isPidAlive(0)).toBe(false);
    expect(isPidAlive(-5)).toBe(false);
    expect(isPidAlive(1.5)).toBe(false);
  });
});

describe("shim registration", () => {
  it("registers and unregisters a pidfile", () => {
    const file = registerShim(tmpRoot, process.pid);
    expect(file).toBe(path.join(tmpRoot, SHIM_PID_DIR, `${process.pid}.pid`));
    expect(fs.existsSync(file)).toBe(true);
    unregisterShim(tmpRoot, process.pid);
    expect(fs.existsSync(file)).toBe(false);
  });

  it("unregister is safe when never registered", () => {
    expect(() => unregisterShim(tmpRoot, 12345)).not.toThrow();
  });
});

describe("liveSiblingShims", () => {
  it("excludes self and prunes dead registrations", () => {
    registerShim(tmpRoot, process.pid); // self
    registerShim(tmpRoot, deadPid); // crashed shim
    const siblings = liveSiblingShims(tmpRoot, process.pid);
    expect(siblings).toEqual([]);
    // The dead shim's stale file must have been pruned.
    expect(fs.existsSync(path.join(tmpRoot, SHIM_PID_DIR, `${deadPid}.pid`))).toBe(false);
  });

  it("reports a live sibling", () => {
    // Register our own (live) pid, then ask from the perspective of another shim.
    registerShim(tmpRoot, process.pid);
    const siblings = liveSiblingShims(tmpRoot, deadPid);
    expect(siblings).toEqual([process.pid]);
  });

  it("returns empty when the directory does not exist", () => {
    expect(liveSiblingShims(tmpRoot, process.pid)).toEqual([]);
  });

  it("prunes unparseable entries", () => {
    fs.mkdirSync(path.join(tmpRoot, SHIM_PID_DIR), { recursive: true });
    fs.writeFileSync(path.join(tmpRoot, SHIM_PID_DIR, "garbage.txt"), "x");
    expect(liveSiblingShims(tmpRoot, process.pid)).toEqual([]);
    expect(fs.existsSync(path.join(tmpRoot, SHIM_PID_DIR, "garbage.txt"))).toBe(false);
  });
});

describe("spawned server record", () => {
  it("records and reads the backend pid", () => {
    recordSpawnedServer(tmpRoot, 4242);
    expect(readSpawnedServerPid(tmpRoot)).toBe(4242);
    clearSpawnedServer(tmpRoot);
    expect(readSpawnedServerPid(tmpRoot)).toBeNull();
  });

  it("does not clobber a live backend's record (concurrent-spawn loser)", () => {
    recordSpawnedServer(tmpRoot, process.pid); // "live" backend
    recordSpawnedServer(tmpRoot, 99999999); // loser tries to record its dead child
    expect(readSpawnedServerPid(tmpRoot)).toBe(process.pid);
  });

  it("replaces a dead backend's record", () => {
    recordSpawnedServer(tmpRoot, deadPid);
    recordSpawnedServer(tmpRoot, process.pid);
    expect(readSpawnedServerPid(tmpRoot)).toBe(process.pid);
  });

  it("readSpawnedServerPid rejects garbage content", () => {
    fs.writeFileSync(path.join(tmpRoot, SERVER_PIDFILE), "not-a-pid\n");
    expect(readSpawnedServerPid(tmpRoot)).toBeNull();
  });
});

describe("backendPidToReap — the T14 kill decision", () => {
  it("never kills while another live shim is registered", () => {
    recordSpawnedServer(tmpRoot, process.pid); // pretend backend is alive
    registerShim(tmpRoot, process.pid); // a live sibling (our own pid, seen from selfPid=deadPid)
    expect(backendPidToReap(tmpRoot, deadPid)).toBeNull();
  });

  it("returns the backend pid when this is the last shim", () => {
    recordSpawnedServer(tmpRoot, process.pid);
    expect(backendPidToReap(tmpRoot, process.pid)).toBe(process.pid);
  });

  it("returns null when no backend was auto-spawned (manual servers are never killed)", () => {
    expect(backendPidToReap(tmpRoot, process.pid)).toBeNull();
  });

  it("clears the record and returns null when the backend already died", () => {
    recordSpawnedServer(tmpRoot, deadPid);
    expect(backendPidToReap(tmpRoot, process.pid)).toBeNull();
    expect(readSpawnedServerPid(tmpRoot)).toBeNull();
  });

  it("ignores stale registrations from crashed shims", () => {
    recordSpawnedServer(tmpRoot, process.pid);
    registerShim(tmpRoot, deadPid); // crashed shim never unregistered
    expect(backendPidToReap(tmpRoot, process.pid)).toBe(process.pid);
  });
});

import { describe, expect, it } from "vitest";
import { isHumanProfile } from "./health";

/**
 * `isHumanProfile` decides which backend profiles a person is ever shown —
 * including the auto-select that picks one on first load. When it was too
 * permissive the app opened on `.mcp-shims`, and every surface then truthfully
 * reported an empty profile: the graph failed to load, geo had no coordinates,
 * tasks answered 400. That reads as a broken product when the only thing wrong
 * is the selection, so each exclusion below is pinned individually.
 */
describe("isHumanProfile", () => {
  it("accepts ordinary human profiles", () => {
    for (const p of ["varun", "analyst-1", "gdelt-bridge", "demo", "a"]) {
      expect(isHumanProfile(p)).toBe(true);
    }
  });

  it("rejects the seat harness store", () => {
    // The seat writes its lessons to `<user>.seat-harness`, a real per-user
    // store — so /api/users lists it like any other profile. A session opened
    // on it would read machinery as memory.
    expect(isHumanProfile("varun.seat-harness")).toBe(false);
    expect(isHumanProfile(".seat-harness")).toBe(false);
  });

  it("rejects dot-prefixed internal directories", () => {
    // The regression: `.mcp-shims` sorted first, so first load selected it.
    expect(isHumanProfile(".mcp-shims")).toBe(false);
    expect(isHumanProfile(".internal")).toBe(false);
    expect(isHumanProfile(".")).toBe(false);
  });

  it("rejects test fixtures left behind by PR work", () => {
    expect(isHumanProfile("test")).toBe(false);
    expect(isHumanProfile("test-recall")).toBe(false);
    expect(isHumanProfile("smoke-test")).toBe(false);
  });

  it("does not reject human profiles that merely contain the word test", () => {
    // Guards against widening the filter into a substring match, which would
    // silently hide a real corpus.
    expect(isHumanProfile("contested")).toBe(true);
    expect(isHumanProfile("latest-intel")).toBe(true);
    expect(isHumanProfile("protest-monitoring")).toBe(true);
  });

  it("does not reject profiles that merely contain a dot", () => {
    expect(isHumanProfile("varun.sharma")).toBe(true);
    expect(isHumanProfile("gdelt.2026")).toBe(true);
  });

  it("currently accepts the empty string — documented, not endorsed", () => {
    // None of the five predicates excludes "", so it passes. The backend is not
    // expected to return it, and this test exists to make that assumption
    // visible: if /api/users ever yields "", the switcher gets a blank row
    // rather than an error, and this is where that gets noticed.
    expect(isHumanProfile("")).toBe(true);
  });
});
